# Las operaciones de la API, para GET /api. Es la fuente de verdad del CLI y
# del futuro MCP: cada endpoint nuevo se añade aquí.
module Api::Operations
  VERSION = 1

  ALL = [
    { method: "GET", path: "/api", params: {}, command: nil,
      description: "API version and list of operations. Needs no token" },
    { method: "GET", path: "/api/projects", params: {}, command: "mt projects",
      description: "Projects: key, name, current milestone and how many stories are in progress" },
    { method: "POST", path: "/api/projects", params: { name: "the project's name", key: "2 to 5 letters, like PG" },
      command: "mt project create \"Name\" --key PG", description: "Creates a project with the brief template. VALIDATION_FAILED if the key exists" },

    # Leer (#016). Lo que lee un agente va también en data.markdown (docs/CLI.md).
    { method: "GET", path: "/api/projects/:key/context", params: {}, command: "mt context",
      description: "Brief (the cover), the index of the documentation, the done stories with documentation pending, latest decisions in force, current milestone and what is in progress" },
    { method: "GET", path: "/api/projects/:key/next", params: {}, command: "mt next",
      description: "First ready, unblocked story of the open milestones, whole and with why. NOTHING_READY if there is none" },
    { method: "GET", path: "/api/projects/:key/workshop", params: {}, command: "mt workshop",
      description: "What the person has to define next in the project, in roadmap order (at most 5, the same as the app's workshop): each story with the one thing it is missing (answer a question, write criteria, design, review and OK) and the command that closes it; then how many more are defining and how many are ready" },
    { method: "GET", path: "/api/projects/:key/roadmap", params: { closed: "true to include closed milestones" }, command: "mt roadmap [--closed]",
      description: "Open milestones in order with their goal and stories in order, then the inbox" },
    { method: "GET", path: "/api/projects/:key/stories", command: "mt list [--state …] [--milestone …] [--label …] [--mine]",
      params: { state: "idea | defining | ready | in_progress | done", milestone: "M2, its title or inbox", label: "a label", claimed_by: "actor name or me" },
      description: "Lists stories with filters" },
    { method: "GET", path: "/api/projects/:key/stories/:number", params: {}, command: "mt show PG-49",
      description: "A story as markdown with frontmatter (the docs/backlog/ format), with related stories, its decisions (in force or superseded), comments and latest events" },
    { method: "GET", path: "/api/projects/:key/decisions", params: { capability: "a page slug (optional): only the decisions governing it" }, command: "mt decisions [--capability board]",
      description: "All decisions, newest first, marking the superseded ones" },
    { method: "GET", path: "/api/projects/:key/check", params: { text: "the proposal, in free text (POST with it in the body if it is long)" },
      command: "mt check \"…\" | mt check --file f.md",
      description: "Checks a proposal against the project: up to 10 candidates, decisions (in force or superseded, with the one that supersedes them), stories of any state and fragments of the brief, most relevant first (SQLite FTS5 over titles, bodies, whys, comments and the brief), each with who, when, an excerpt and the words that match. Judging whether it clashes is the agent's job" },

    # La daily (MT-42). Es un POST porque deja constancia de la daily del actor.
    { method: "POST", path: "/api/projects/:key/daily", params: { since: "a date like 2026-10-15 or 2026-10-15 22:40; without it, since the actor's last daily (or the last 7 days if none)" },
      command: "mt daily [--since date]",
      description: "The project's daily for the token's actor: what happened since their last daily, in progress, blocked, waiting for the human and what is next. Records the daily, so the next one starts here; another actor's is not moved" },
    { method: "POST", path: "/api/projects/:key/daily/ideas", params: { title: "the evolutionary idea", why: "markdown for the Contexto section (optional)" },
      command: "mt daily idea \"…\" [--why \"…\"]",
      description: "Proposes an evolutionary as an idea in the inbox, never in the roadmap. At most 3 per daily; VALIDATION_FAILED if the actor has not done their daily or has reached the limit" },

    # Trabajar (#017). Todo queda a nombre del actor del token, con su evento.
    { method: "POST", path: "/api/projects/:key/stories/:number/start", params: {}, command: "mt start PG-49",
      description: "Claims the story and moves it to in_progress. CLAIMED_BY_OTHER if someone else has it; warnings if it was not ready, is blocked or has no criteria" },
    { method: "POST", path: "/api/projects/:key/stories/:number/done", params: { commits: "list of shas, or of {sha, message} (optional)", pr: "PR url (optional)" },
      command: "mt done PG-49 [--commit sha]… [--pr url]",
      description: "Moves the story to done with its commits and PR in the event, linking the pages of its capabilities edited since it started. The rest are marked documentation pending (a warning, it still closes); calling it again on a done story links the pending ones edited since" },
    { method: "POST", path: "/api/projects/:key/stories/:number/release", params: { reason: "why you release it (required for agents)" },
      command: "mt release PG-49 --reason \"…\"", description: "Moves it back to ready and unclaims it" },
    { method: "POST", path: "/api/projects/:key/stories/:number/comments", params: { body: "markdown" },
      command: "mt comment PG-49 \"…\"", description: "Comments on the story" },
    { method: "POST", path: "/api/projects/:key/stories/:number/attachments", params: { file: "the file, as multipart/form-data", alt: "the image's caption (optional)" },
      command: "mt attach PG-49 <file>",
      description: "Attaches a screenshot, video or file (up to 100 MB: images, videos, PDF, text, archives) to the story. Returns its markdown line by name, ![name](attachment:name.png), to paste in the body as is (never copy attachment URLs): images and videos are seen inline, the rest downloads, HTML included" },
    { method: "POST", path: "/api/projects/:key/docs/:slug/attachments", params: { file: "the file, as multipart/form-data", alt: "the image's caption (optional)" },
      command: "mt attach board <file>",
      description: "Attaches a file to a documentation page, like a story's. The page's images, in upload order, are its screenshots (the cover's and those of a capability's walkthrough)" },
    { method: "POST", path: "/api/projects/:key/decisions", params: { title: "the decision", body: "the why (markdown)", story: "PG-49 (optional)", supersedes: "D-9 (optional)", capabilities: "page slugs it governs (optional, a list); it also inherits its story's and those of the one it supersedes" },
      command: "mt decide \"…\" --why \"…\" [--story PG-49] [--supersedes D-9] [--capability board]…", description: "Records a decision. Returns its reference (D-15)" },
    { method: "POST", path: "/api/projects/:key/decisions/link", params: { decisions: "decision references (D-45, a list)", capabilities: "page slugs they will govern (a list): capabilities or cross-cutting, not the cover" },
      command: "mt decision link D-45 [D-52…] --capability board…", description: "Links decisions that already exist to the pages they govern, without superseding them. Linking twice does not duplicate. Records decision.linked with the new links" },
    { method: "POST", path: "/api/projects/:key/decisions/unlink", params: { decisions: "decision references (D-45, a list)", capabilities: "page slugs (a list)" },
      command: "mt decision unlink D-45 [D-52…] --capability board…", description: "Removes those links; the decisions stay. Records decision.unlinked with the removed links" },

    # Preguntas con opciones (MT-29). Bloquean por defecto la historia hasta que se contestan.
    { method: "POST", path: "/api/projects/:key/stories/:number/questions", command: "mt ask PG-49 \"…\" --option \"…\" --option \"…\" [--recommend 2] [--context \"…\"] [--reversible] [--no-bloqueante]",
      params: { title: "the question", context: "markdown (optional)", options: "list of at least 2 texts", recommended: "number of the recommended option (required if it does not block)",
                reversible: "true if the decision can be undone; without it, not stated", blocking: "false to let the agent carry on with the recommended option (default true)" },
      description: "Asks a question in the story in the actor's name. A blocking one releases the story if it was the actor's, and the story is blocked by the person who answers until it is answered" },
    { method: "POST", path: "/api/projects/:key/stories/:number/answer", command: "mt answer PG-49 2 [--note \"…\"] [--question 12] [--decide] | mt answer PG-49 --text \"…\"",
      params: { option: "number of the chosen option (optional if you answer with text)", text: "your own answer, when no option fits; use it instead of option", note: "markdown (optional, goes with the option)", question: "id of the question (Q12 or 12); needed if the story has several open", decide: "true to also record it as a decision" },
      description: "Answers an open question. The story is available again when no blocking questions are left. ALREADY_ANSWERED if it was answered" },
    { method: "GET", path: "/api/questions", params: { project: "a project key (optional)" }, command: "mt questions [--project PG]",
      description: "Open questions of all the projects (or one), the one waiting the longest first, with their options" },

    # Lo desplegado (MT-46): el CLI decide con git, la API no necesita el repo.
    { method: "GET", path: "/api/projects/:key/deployed", command: "mt deployed [<sha>]",
      description: "The candidates of a deploy: stories done and not deployed yet (once the project deploys, only those done since its first deploy), with the commits and the PR of their done event. active says if the project already deploys with mt" },
    { method: "POST", path: "/api/projects/:key/deployed", params: { sha: "the deployed commit", stories: "list of story numbers the sha contains" },
      command: "mt deployed [<sha>]",
      description: "Marks those stories as deployed and records the deploy. Calling again with the same or a later sha is idempotent. Any actor can call it" },

    # Coste por historia (MT-34): una estimación que reporta el hook SessionEnd de Claude Code (o wflow).
    { method: "POST", path: "/api/projects/:key/usage", command: "mt usage <transcript.jsonl> [--story 49] | mt usage --hook",
      params: { source: "claude-code | wflow…", session_id: "", started_at: "ISO 8601, first instant of the session", ended_at: "ISO 8601, last instant",
                models: "list of { model, input, output, cache_read, cache_write_5m, cache_write_1h }: the ACCUMULATED totals of the session",
                story: "number (optional); skips the resolution" },
      description: "Reports the tokens a session used. The server prices them (config/model_prices.yml), picks the story (the last one this actor started that was in progress during the session; none, nothing is reported) and records usage.reported with only what is new since the last report of the same source + session_id. A model without a price keeps its tokens and is listed in unpriced_models" },

    # Definir producto (#018). Nada se borra; cada cambio deja su evento.
    { method: "POST", path: "/api/projects/:key/stories", command: "mt create \"Title\" [--milestone M2] [--state …] [--number 14] [--file f.md]",
      params: { markdown: "the story in the mt show format (or the separate fields)", title: "", milestone: "M2, its title or inbox", state: "idea | defining | ready",
                body: "markdown; without it, the template", mockup: "url", labels: "list", blocked_by: "list of numbers",
                capabilities: "list of page slugs: the capabilities it changes",
                number: "keeps this number if it is free (to migrate a backlog); without it, the next one" },
      description: "Creates a story. Without state it is an idea, and without milestone it goes to the inbox" },
    { method: "PATCH", path: "/api/projects/:key/stories/:number", command: "mt edit PG-49 --file f.md",
      params: { markdown: "the story in the mt show format", version: "the version you read (the version: line of mt show); optional", title: "", body: "", mockup: "", labels: "", blocked_by: "", capabilities: "list of page slugs" },
      description: "Edits title, body and properties; number is ignored. CONFLICT (409, nothing saved) if the version is not the current one. Changing state or milestone is an error: use move or reorder" },
    { method: "POST", path: "/api/projects/:key/stories/:number/move", params: { state: "idea | defining | ready | in_progress | done" },
      command: "mt move PG-49 ready", description: "Changes the state. Moving to ready without meeting the rule gives warnings" },
    { method: "POST", path: "/api/projects/:key/stories/:number/reorder", command: "mt reorder PG-49 --position 1 [--milestone M3] --reason \"…\"",
      params: { position: "from 1; without it, at the end", milestone: "M3, its title or inbox", reason: "required for agents" },
      description: "Reorders the story in its milestone or moves it to another" },
    { method: "POST", path: "/api/projects/:key/milestones", params: { title: "", goal: "markdown" },
      command: "mt milestone create \"Title\" [--goal \"…\"]", description: "Creates a milestone at the end of the roadmap" },
    { method: "GET", path: "/api/projects/:key/milestones/:code", params: {}, command: "mt milestone show M2",
      description: "A milestone with its version (the one to send when editing it)" },
    { method: "PATCH", path: "/api/projects/:key/milestones/:code", params: { title: "", goal: "markdown", version: "the version you read; optional" },
      command: "mt milestone edit M2 [--title …] [--goal …] [--version n]", description: "Edits a milestone's title or goal. CONFLICT (409, nothing saved) if the version is not the current one" },
    { method: "POST", path: "/api/projects/:key/milestones/:code/reorder", params: { position: "from 1", reason: "required for agents" },
      command: "mt milestone reorder M3 --position 2 --reason \"…\"", description: "Changes a milestone's position; its code stays the same" },
    { method: "POST", path: "/api/projects/:key/milestones/:code/close", params: {}, command: "mt milestone close M2", description: "Closes a milestone" },
    { method: "POST", path: "/api/projects/:key/milestones/:code/reopen", params: {}, command: "mt milestone reopen M2", description: "Reopens a milestone" },
    { method: "GET", path: "/api/projects/:key/brief", params: {}, command: "mt brief", description: "The brief as markdown, with its version in a frontmatter" },
    { method: "PUT", path: "/api/projects/:key/brief", params: { markdown: "the whole brief; a leading version: frontmatter is checked", version: "optional, instead of the frontmatter" },
      command: "mt brief --file f.md", description: "Replaces the brief. CONFLICT (409, nothing saved) if the version is not the current one" },

    # Documentación (MT-89): la portada (el brief, slug cover), capacidades y transversales.
    { method: "GET", path: "/api/projects/:key/docs", params: {}, command: "mt doc",
      description: "The documentation pages: the cover (the brief), the capabilities and the cross-cutting pages, one line each" },
    { method: "GET", path: "/api/projects/:key/docs/:slug", params: {}, command: "mt doc board",
      description: "A page as markdown with frontmatter (slug, version, type, title, icon, area), the decisions in force that govern it, how it has changed (the stories whose closing updated it) and its latest events" },
    # mt doc lint (MT-123): cómo se leerá en la web, con el mismo Page::Reading.
    { method: "GET", path: "/api/projects/:key/docs/:slug/lint", params: {}, command: "mt doc lint board",
      description: "How a page will read on the web: its opening sentence, how many rules and questions it finds, the sections that will show as prose, cited decisions and stories that do not exist or are superseded, and images that do not load or are not its attachments. data.errors > 0 means it does not read well (mt exits with 1)" },
    { method: "GET", path: "/api/projects/:key/docs/lint", params: {}, command: "mt doc lint --all",
      description: "The same for every capability and cross-cutting page" },
    { method: "POST", path: "/api/projects/:key/docs", command: "mt doc create board --title \"Board\" [--type …] [--area …] [--icon …] [--file f.md]",
      params: { slug: "lowercase letters, numbers and hyphens", title: "", type: "capability (default) | crosscutting", area: "optional", icon: "optional", body: "markdown", markdown: "the mt doc format instead of the fields" },
      description: "Creates a capability or a cross-cutting page. Agents ask before creating, splitting, merging or deleting capabilities" },
    { method: "PATCH", path: "/api/projects/:key/docs/:slug", params: { markdown: "the page in the mt doc format; its version: is checked", title: "", type: "", area: "", icon: "", body: "", version: "optional, instead of the frontmatter" },
      command: "mt doc edit board --file f.md", description: "Edits a page (the cover is the brief). CONFLICT (409, nothing saved) if the version is not the current one" },
    { method: "DELETE", path: "/api/projects/:key/docs/:slug", params: {}, command: "mt doc delete board",
      description: "Deletes a capability or cross-cutting page; the cover is not deleted. Agents ask first" }
  ].freeze
end
